111	export function getAutoModelDescription(
112	  hasAccessToPreview: boolean,
113	  useGemini3_1: boolean = false,
114	) {
115	  const proModel = hasAccessToPreview
116	    ? useGemini3_1
117	      ? PREVIEW_GEMINI_3_1_MODEL
118	      : PREVIEW_GEMINI_MODEL
119	    : DEFAULT_GEMINI_MODEL;
120	  const flashModel = hasAccessToPreview
121	    ? PREVIEW_GEMINI_FLASH_MODEL
122	    : DEFAULT_GEMINI_FLASH_MODEL;
123	  return `Let Gemini CLI decide the best model for the task: ${proModel}, ${flashModel}`;
124	}
