48	export const ModelStatsDisplay: React.FC<ModelStatsDisplayProps> = ({
49	  selectedAuthType,
50	  userEmail,
51	  tier,
52	  currentModel,
53	  quotaStats,
54	}) => {
55	  const { stats } = useSessionStats();
56	
57	  const pooledRemaining = quotaStats?.remaining;
58	  const pooledLimit = quotaStats?.limit;
59	  const pooledResetTime = quotaStats?.resetTime;
60	
61	  const { models } = stats.metrics;
62	  const settings = useSettings();
63	  const showUserIdentity = settings.merged.ui.showUserIdentity;
64	  const activeModels = Object.entries(models).filter(
65	    ([, metrics]) => metrics.api.totalRequests > 0,
66	  );
67	
68	  if (activeModels.length === 0) {
69	    return (
70	      <Box
71	        borderStyle="round"
72	        borderColor={theme.border.default}
73	        paddingTop={1}
74	        paddingX={2}
75	      >
76	        <Text color={theme.text.primary}>
77	          No API calls have been made in this session.
78	        </Text>
79	      </Box>
80	    );
81	  }
82	
83	  const modelNames = activeModels.map(([name]) => name);
84	
85	  const hasThoughts = activeModels.some(
86	    ([, metrics]) => metrics.tokens.thoughts > 0,
87	  );
88	  const hasTool = activeModels.some(([, metrics]) => metrics.tokens.tool > 0);
89	  const hasCached = activeModels.some(
90	    ([, metrics]) => metrics.tokens.cached > 0,
91	  );
92	
93	  const allRoles = [
94	    ...new Set(
95	      activeModels.flatMap(([, metrics]) => Object.keys(metrics.roles ?? {})),
96	    ),
97	  ]
98	    .filter((role): role is LlmRole => {
99	      const validRoles: string[] = Object.values(LlmRole);
100	      return validRoles.includes(role);
101	    })
102	    .sort((a, b) => {
103	      if (a === b) return 0;
104	      if (a === LlmRole.MAIN) return -1;
105	      if (b === LlmRole.MAIN) return 1;
106	      return a.localeCompare(b);
107	    });
108	
109	  // Helper to create a row with values for each model
110	  const createRow = (
111	    metric: string,
112	    getValue: (
113	      metrics: (typeof activeModels)[0][1],
114	    ) => string | React.ReactNode,
115	    options: { isSection?: boolean; isSubtle?: boolean } = {},
116	  ): StatRowData => {
117	    const row: StatRowData = {
118	      metric,
119	      isSection: options.isSection,
120	      isSubtle: options.isSubtle,
121	    };
122	    activeModels.forEach(([name, metrics]) => {
123	      row[name] = getValue(metrics);
124	    });
125	    return row;
126	  };
127	
128	  const rows: StatRowData[] = [];
129	
130	  // API Section
131	  rows.push({ metric: 'API', isSection: true });
132	  rows.push(createRow('Requests', (m) => m.api.totalRequests.toLocaleString()));
133	  rows.push(
134	    createRow('Errors', (m) => {
135	      const errorRate = calculateErrorRate(m);
136	      return (
137	        <Text
138	          color={
139	            m.api.totalErrors > 0 ? theme.status.error : theme.text.primary
